def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]

    if n < 3:
        return 'C'

    opp_c = n - opp.count('D')
    opp_d = n - opp_c
    my_d = me.count('D')

    if opp_d == 0:
        if n >= 92:
            return 'D'
        if n >= 80 and rng.random() < 0.15:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'

    recent = opp[-10:]
    rc = recent.count('C')
    rd = len(recent) - rc
    if rd >= 8:
        return 'D'
    if rc >= 9:
        if n < 90:
            return 'D'
        return 'C'

    if last_opp == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                run += 1
            else:
                break
        if run >= 3:
            return 'D'
        if run == 2:
            return 'D'
        if opp_c * 2 >= n and rc >= 6:
            return 'C'
        if my_d * 3 > n:
            return 'C'
        return 'D'

    if n >= 90:
        if opp_c * 3 >= n * 2:
            return 'D'
        return 'C'

    if rd >= 4 and rc >= 4:
        if last_me == 'D':
            return 'C'
        return 'C'

    if rc >= 7:
        return 'C'

    return 'C'
